package com.citacloud.app.views; import com.citacloud.app.models.AuditoriaEvento; import com.citacloud.app.security.*; import com.citacloud.app.services.AuditoriaService; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.orderedlayout.VerticalLayout; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.util.*;
@Route(value="auditoria",layout=MainLayout.class) @PageTitle("Auditoría | CitaCloud") @PermitAll public class AuditoriaView extends VerticalLayout {public AuditoriaView(AuditoriaService service){TenantUserDetails u=AuthService.getAuthenticatedUser();UUID empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);add(new H2("Auditoría"),new Paragraph("Operaciones registradas para la empresa autenticada."));Grid<AuditoriaEvento> grid=new Grid<>(AuditoriaEvento.class,false);grid.addColumn(AuditoriaEvento::getFecha).setHeader("FECHA");grid.addColumn(AuditoriaEvento::getModulo).setHeader("MÓDULO");grid.addColumn(AuditoriaEvento::getAccion).setHeader("ACCIÓN");grid.addColumn(AuditoriaEvento::getEntidad).setHeader("ENTIDAD");grid.setItems(empresa==null?List.of():service.listar(empresa));grid.setWidthFull();add(grid);}}
